var asString = (v) => typeof v === "string" && v.length > 0 ? v : null;
function payloadFactions(event) {
  const out = [];
  const push = (v) => {
    const s = asString(v);
    if (s !== null && !out.includes(s)) out.push(s);
  };
  push(event["factionId"]);
  push(event["seatId"]);
  push(event["from"]);
  push(event["to"]);
  push(event["a"]);
  push(event["b"]);
  push(event["winner"]);
  push(event["buyer"]);
  push(event["seller"]);
  return out;
}
function stateFactions(event, state) {
  if (state === void 0) return [];
  const out = [];
  const unitId = asString(event["unitId"]);
  if (unitId !== null) {
    const owner = state.units[unitId]?.ownerId;
    if (owner !== void 0 && owner !== "neutral" && !out.includes(owner)) out.push(owner);
  }
  for (const key of ["regionId", "to", "from"]) {
    const rid = asString(event[key]);
    if (rid === null) continue;
    const owner = state.regions[rid]?.owner;
    if (owner !== null && owner !== void 0 && !out.includes(owner)) out.push(owner);
  }
  return out;
}
function audienceOfEvent(event, state) {
  const ev = event ?? {};
  const type = asString(ev["type"]);
  if (type === null) return [];
  const visibility = EVENT_VISIBILITY[type];
  if (visibility === void 0) return [];
  if (visibility === "all") return "all";
  if (visibility === "public-only") {
    if (ev["publicity"] === "public") return "all";
    const parties = [...payloadFactions(ev), ...stateFactions(ev, state)];
    return dedupe(parties.filter((p) => p !== "spectator"));
  }
  if (type === "message_delivered" && ev["to"] === null) return "all";
  return dedupe([...payloadFactions(ev), ...stateFactions(ev, state)]);
}
function unionAudience(a, b) {
  if (a === "all" || b === "all") return "all";
  return dedupe([...a, ...b]);
}
function audienceIncludes(audience, recipientFaction) {
  if (recipientFaction === "spectator" || recipientFaction === null) return true;
  if (audience === "all") return true;
  return audience.includes(recipientFaction);
}
function dedupe(list) {
  const out = [];
  for (const v of list) if (!out.includes(v)) out.push(v);
  return out.sort();
}

